import { DefaultData, Schema, type GoblinState } from './schema';

export const 冒险者性别选项 = ['男', '女', '其他'] as const;
export const 巢穴阶段预设 = ['初成巢穴', '扩张中巢穴', '稳固巢穴', '饥渴高压期'] as const;
export const 巢穴风格预设 = ['伏击围猎', '拖拽分割', '夜间骚扰', '潮湿困杀'] as const;
export const 压力等级预设 = ['低压', '中压', '高压', '崩溃边缘'] as const;
export const 主导方预设 = ['僵持', '哥布林', '冒险者'] as const;
export const 成人基调预设 = ['威胁逼近', '俘获压迫', '羞辱失衡', '繁殖意图显著'] as const;
export const 哥布林族类预设 = ['普通哥布林', '洞窟斥候', '驯兽哥布林', '重棍哥布林', '灰皮祭司'] as const;
export const 哥布林职能预设 = ['前哨', '拦截', '围猎', '押送', '看守'] as const;

export const 最大冒险者数 = 4;
export const 最大哥布林数 = 6;

export interface 冒险者表单项 {
  id: string;
  姓名: string;
  性别: (typeof 冒险者性别选项)[number];
  职业: string;
  特性: string;
  背景: string;
  战斗倾向: string;
  外观摘要: string;
  装备摘要: string;
  弱点破绽: string;
  欲望倾向: string;
  补充说明: string;
}

export interface 哥布林表单项 {
  id: string;
  姓名: string;
  族类: string;
  职能: string;
  特性: string;
  背景: string;
  外观摘要: string;
  装备摘要: string;
  弱点破绽: string;
  欲望倾向: string;
  补充说明: string;
}

export interface 推演表单 {
  巢穴设定: {
    名称: string;
    阶段: string;
    地形: string;
    风格: string;
    当前氛围: string;
    警戒: number;
    战备: number;
  };
  冒险者: 冒险者表单项[];
  哥布林: 哥布林表单项[];
  遭遇种子: {
    标题: string;
    目标: string;
    压力等级: string;
    当前地点: string;
    局势描述: string;
    主导方: (typeof 主导方预设)[number];
    战局标签: string;
    待决节点: string;
  };
  成人设定: {
    后果基调: (typeof 成人基调预设)[number];
    推演偏好: string;
    风险备注: string;
  };
  自定义开局补充: string;
}

function 清洗文本(value: string, fallback = '') {
  return value.trim() || fallback;
}

function 制作编号(prefix: string, label: string, index: number) {
  const base = _.kebabCase(label.trim()) || `${prefix}-${index}`;
  return `${prefix}-${base}-${index}`;
}

function 拆分短句列表(value: string, max = 6) {
  return _(value.split(/[\r\n,，、;；|/]+/))
    .map(item => item.trim())
    .filter(Boolean)
    .uniq()
    .take(max)
    .value();
}

function 构建身体状态(type: 'adv' | 'gob') {
  if (type === 'adv') {
    return {
      胸部: '护具完整',
      私处: '未观察',
      肛门: '未观察',
      嘴: '呼吸急促',
      衣物: '旅行装束整齐',
      四肢: '行动自由',
      其他: '行动前整备完成',
    };
  }

  return {
    胸部: '粗糙皮甲',
    私处: '躁动未发作',
    肛门: '无异常',
    嘴: '獠牙外露',
    衣物: '脏旧皮带与碎布',
    四肢: '半蹲蓄势',
    其他: '泥污与旧血未清',
  };
}

export function 创建空冒险者(index: number): 冒险者表单项 {
  return {
    id: `adv-${index}`,
    姓名: '',
    性别: '女',
    职业: '',
    特性: '',
    背景: '',
    战斗倾向: '',
    外观摘要: '',
    装备摘要: '',
    弱点破绽: '',
    欲望倾向: '',
    补充说明: '',
  };
}

export function 创建空哥布林(index: number): 哥布林表单项 {
  return {
    id: `gob-${index}`,
    姓名: '',
    族类: 哥布林族类预设[(index - 1) % 哥布林族类预设.length],
    职能: 哥布林职能预设[(index - 1) % 哥布林职能预设.length],
    特性: '',
    背景: '',
    外观摘要: '',
    装备摘要: '',
    弱点破绽: '',
    欲望倾向: '',
    补充说明: '',
  };
}

export function 创建默认推演表单(source: GoblinState = DefaultData): 推演表单 {
  return {
    巢穴设定: {
      名称: source.巢穴.名称,
      阶段: source.巢穴.阶段,
      地形: source.巢穴.地形,
      风格: source.巢穴.风格,
      当前氛围: source.世界.当前氛围,
      警戒: source.巢穴.储备.警戒,
      战备: source.巢穴.储备.战备,
    },
    冒险者: [创建空冒险者(1)],
    哥布林: [创建空哥布林(1), 创建空哥布林(2)],
    遭遇种子: {
      标题: '洞口伏击',
      目标: '判断谁先抢到地利、主导权以及第一轮压制资格。',
      压力等级: '中压',
      当前地点: source.巢穴.地形,
      局势描述: '一支刚刚靠近巢穴的冒险者小队，与已提前布点的哥布林前哨在狭窄入口附近接触。',
      主导方: '僵持',
      战局标签: '侦察接触, 潮湿洞窟, 火把试探',
      待决节点: '谁先暴露破绽, 谁被拖进狭窄地段, 第一名俘获候选是谁',
    },
    成人设定: {
      后果基调: '俘获压迫',
      推演偏好: '突出俘获、控制、羞辱与繁殖意图对局势的推动，不脱离战况主线。',
      风险备注: '正文可以显著写出压迫、屈服和身体反应，但避免无止境堆砌器官细节。',
    },
    自定义开局补充: '',
  };
}

function 取有效冒险者(form: 推演表单) {
  return form.冒险者.filter(item => item.姓名.trim() && item.职业.trim());
}

function 取有效哥布林(form: 推演表单) {
  return form.哥布林.filter(item => item.姓名.trim() && item.职能.trim());
}

export function 校验推演表单(form: 推演表单) {
  if (!清洗文本(form.巢穴设定.名称) || !清洗文本(form.巢穴设定.地形) || !清洗文本(form.遭遇种子.标题)) {
    return '巢穴名称、地形和遭遇标题是必填项。';
  }
  if (!清洗文本(form.遭遇种子.目标) || !清洗文本(form.遭遇种子.局势描述)) {
    return '遭遇目标和局势描述不能留空。';
  }
  const adventurers = 取有效冒险者(form);
  const goblins = 取有效哥布林(form);
  if (adventurers.length === 0) {
    return '至少需要 1 名已填写姓名和职业的冒险者。';
  }
  if (goblins.length === 0) {
    return '至少需要 1 只已填写姓名和职能的哥布林。';
  }
  if (adventurers.length > 最大冒险者数 || goblins.length > 最大哥布林数) {
    return '当前出场人数超出本项目允许范围。';
  }
  return '';
}

