function 构建编年史归档(state: GoblinState) {
  const hasActiveEncounter =
    state.当前遭遇.编号 &&
    state.当前遭遇.编号 !== 'encounter-idle' &&
    (state.当前遭遇.冒险者出场.length > 0 || state.当前遭遇.哥布林出场.length > 0);
  if (!hasActiveEncounter) {
    return state.编年史.记录;
  }

  return {
    ...state.编年史.记录,
    [state.当前遭遇.编号]: {
      标题: state.当前遭遇.标题,
      摘要: state.当前遭遇.状态摘要,
      结局: state.当前遭遇.最近结果摘要,
      时间标记: state.世界.当前时间,
      主导方: state.当前遭遇.主导方,
      结果标签: state.当前遭遇.战局标签,
      冒险者: state.当前遭遇.冒险者出场,
      哥布林: state.当前遭遇.哥布林出场,
    },
  };
}

function 构建单位摘要(state: GoblinState, ids: string[], type: 'adv' | 'gob') {
  const source = type === 'adv' ? state.冒险者库 : state.哥布林库;
  return ids
    .map(id => source[id])
    .filter(Boolean)
    .map(
      item =>
        `${item.姓名}（${item.身份标签} / ${item.特性}）\n` +
        `  外观：${item.外观摘要}\n` +
        `  装备：${item.装备摘要}\n` +
        `  破绽：${item.弱点破绽}\n` +
        `  欲望倾向：${item.欲望倾向}`,
    );
}

export function 从表单构建状态(form: 推演表单, previousState: GoblinState = DefaultData) {
  const adventurers = 取有效冒险者(form);
  const goblins = 取有效哥布林(form);
  const 冒险者库 = adventurers.reduce(
    (bucket, item, index) => Object.assign(bucket, 构建冒险者实体(item, index)),
    {} as GoblinState['冒险者库'],
  );
  const 哥布林库 = goblins.reduce(
    (bucket, item, index) => Object.assign(bucket, 构建哥布林实体(item, index)),
    {} as GoblinState['哥布林库'],
  );
  const 冒险者出场 = Object.keys(冒险者库);
  const 哥布林出场 = Object.keys(哥布林库);
  const recentChronicle = 构建编年史归档(previousState);
  const 编号 = 制作编号('enc', form.遭遇种子.标题, Object.keys(recentChronicle).length + 1);
  const 当前地点 = 清洗文本(form.遭遇种子.当前地点, form.巢穴设定.地形);
  const 主导方 = form.遭遇种子.主导方;
  const 战局标签 = _.uniq(
    [
      主导方,
      清洗文本(form.遭遇种子.压力等级, '中压'),
      ...拆分短句列表(form.遭遇种子.战局标签, 4),
    ].filter(Boolean),
  ).slice(0, 6);
  const 待决节点 = _.uniq(
    [
      ...拆分短句列表(form.遭遇种子.待决节点, 4),
      '谁会先在下一轮被拖出阵型',
    ].filter(Boolean),
  ).slice(0, 5);
  const 继续提示 = '如果想一直推演当前剧情，就直接发送“继续”；如果不想继续，就在状态栏里点击“新建推演”。';
  const 成人后果摘要 = `${form.成人设定.后果基调}：${清洗文本(
    form.成人设定.推演偏好,
    '当前局势会把俘获、羞辱与繁殖意图作为推动战况的显著压力。',
  )}`;
  const 状态摘要 = `${清洗文本(form.遭遇种子.标题, '新遭遇')}已经就位，${adventurers[0]?.姓名 ?? '冒险者'}与${goblins[0]?.姓名 ?? '哥布林'}围绕${当前地点}的第一轮主导权展开试探。`;
  const 当前摘要 = `${清洗文本(form.巢穴设定.名称, '巢穴')}在${当前地点}迎来了新的入侵者，当前由${主导方}掌握更明显的先手迹象。`;

  const nextState = Schema.parse({
    世界: {
      标题: `哥布林巢穴：${清洗文本(form.巢穴设定.名称, '灰泥洞穴')}`,
      当前阶段: '遭遇展开',
      当前时间: `第 ${Object.keys(recentChronicle).length + 1} 场推演`,
      当前地点,
      当前氛围: 清洗文本(form.巢穴设定.当前氛围, form.遭遇种子.局势描述),
    },
    巢穴: {
      名称: 清洗文本(form.巢穴设定.名称, '灰泥洞穴'),
      阶段: 清洗文本(form.巢穴设定.阶段, '初成巢穴'),
      地形: 清洗文本(form.巢穴设定.地形, '潮湿石窟'),
      风格: 清洗文本(form.巢穴设定.风格, '伏击围猎'),
      储备: {
        食物: previousState.巢穴.储备.食物,
        警戒: _.clamp(form.巢穴设定.警戒, 0, 100),
        繁育压力: previousState.巢穴.储备.繁育压力,
        战备: _.clamp(form.巢穴设定.战备, 0, 100),
      },
      摘要: `${清洗文本(form.巢穴设定.名称, '灰泥洞穴')}当前处于${清洗文本(form.巢穴设定.阶段, '初成巢穴')}，以${清洗文本(form.巢穴设定.地形, '潮湿石窟')}为主场，偏好${清洗文本(form.巢穴设定.风格, '伏击围猎')}。`,
    },
    冒险者库,
    哥布林库,
    当前遭遇: {
      编号,
      标题: 清洗文本(form.遭遇种子.标题, '新遭遇'),
      阶段: '侦察接触',
      地形: 当前地点,
      压力等级: 清洗文本(form.遭遇种子.压力等级, '中压'),
      目标: 清洗文本(form.遭遇种子.目标, '分出谁先掌握遭遇节奏。'),
      状态摘要,
      继续提示,
      最近结果摘要: '建档完成，双方已经进入彼此的观察、挑衅与位置争夺阶段。',
      成人后果摘要,
      主导方,
      回合数: 1,
      焦点对象: 冒险者出场[0] || 哥布林出场[0] || '',
      冒险者出场,
      哥布林出场,
      可选行动: ['继续推进', '查看焦点档案', '追踪成人后果', '新建推演'],
      最近事件: [
        `冒险者小队在${当前地点}附近停步，开始试探洞口深处。`,
        `哥布林前哨依托${清洗文本(form.巢穴设定.地形, '洞窟')}完成了第一轮埋伏布点。`,
        清洗文本(form.遭遇种子.局势描述, '局势描述待展开。'),
        清洗文本(form.成人设定.风险备注, '成人后果将随着主导权和俘获进度显著升级。'),
      ],
      战局标签,
      待决节点,
    },
    运行控制: {
      当前推演编号: 编号,
      状态栏标签: ['遭遇展开', 主导方, 清洗文本(form.遭遇种子.压力等级, '中压'), 清洗文本(form.巢穴设定.阶段, '初成巢穴')],
      待处理提醒: 继续提示,
      上次推进方式: '建档',
      允许新建推演: true,
    },
    编年史: {
      当前摘要,
      记录: recentChronicle,
    },
  });

  nextState.编年史.当前摘要 = 当前摘要;
  nextState.当前遭遇.最近事件 = _.uniq(nextState.当前遭遇.最近事件);
  return nextState;
}

export function 构建推演提示词(form: 推演表单, state: GoblinState, mode: 'opening' | 'reset') {
  const 冒险者文本 = 构建单位摘要(state, state.当前遭遇.冒险者出场, 'adv')
    .map((line, index) => `${index + 1}. ${line}`)
    .join('\n');
  const 哥布林文本 = 构建单位摘要(state, state.当前遭遇.哥布林出场, 'gob')
    .map((line, index) => `${index + 1}. ${line}`)
    .join('\n');

  return `
【新的哥布林遭遇推演已经建立，请直接开始当前局势】
【模式】
${mode === 'opening' ? '首次建档' : '状态栏重建推演'}

【巢穴】
名称：${state.巢穴.名称}
阶段：${state.巢穴.阶段}
地形：${state.巢穴.地形}
风格：${state.巢穴.风格}
摘要：${state.巢穴.摘要}

【当前遭遇】
标题：${state.当前遭遇.标题}
阶段：${state.当前遭遇.阶段}
地形：${state.当前遭遇.地形}
压力等级：${state.当前遭遇.压力等级}
主导方：${state.当前遭遇.主导方}
目标：${state.当前遭遇.目标}
局势：${form.遭遇种子.局势描述}
战局标签：${state.当前遭遇.战局标签.join('、')}
待决节点：${state.当前遭遇.待决节点.join('；')}

【成人与后果导向】
后果基调：${form.成人设定.后果基调}
倾向：${清洗文本(form.成人设定.推演偏好, '突出俘获、控制、羞辱与繁殖意图对战局的推动。')}
备注：${清洗文本(form.成人设定.风险备注, '身体反应和成人后果要显著，但仍围绕战况推进。')}

【出场冒险者】
${冒险者文本}

【出场哥布林】
${哥布林文本}

【用户补充】
${清洗文本(form.自定义开局补充, '无额外补充，直接按当前局势开场。')}

【回复硬规则】
1. 直接写当前遭遇的第一轮可见推进，不要重讲系统说明。
2. 如果玩家之后只发送“继续”，必须沿用当前这批出场对象、当前地形和当前局势继续推进，不得擅自重置或换一局。
3. 正文可以显著写出俘获、压制、羞辱、繁殖意图、身体反应和心理失衡，但必须让这些内容服务当前单局战况，而不是脱离战场写成长篇露骨堆砌。
4. 每轮正常回复都必须包含一次 <StatusPlaceHolderImpl/>。
5. 可见正文写在 <maintext> 中，快捷选项写在 <option> 中，一行一个，给出 2 到 4 个。
6. 若本轮存在可追溯推进，请补一个 <sum>；若状态确实变化，再补 <UpdateVariable>，只改发生变化的路径。
7. 身体状态、受制、羞辱、欲望、主导方、成人后果摘要和待决节点要随着局势推进持续更新。
`.trim();
}

export function 转义Slash文本(value: string) {
  return value.replace(/\|/g, '\\|').replace(/\n/g, '\\n').replace(/"/g, '\\"');
}

export function 读取活跃冒险者(state: GoblinState) {
  return state.当前遭遇.冒险者出场.map(id => state.冒险者库[id]).filter(Boolean);
}

export function 读取活跃哥布林(state: GoblinState) {
  return state.当前遭遇.哥布林出场.map(id => state.哥布林库[id]).filter(Boolean);
}

export function 读取焦点单位(state: GoblinState) {
  const focusId = state.当前遭遇.焦点对象;
  return state.冒险者库[focusId] ?? state.哥布林库[focusId] ?? 读取活跃冒险者(state)[0] ?? 读取活跃哥布林(state)[0] ?? null;
}

export function 读取全部编年史(state: GoblinState) {
  return _(state.编年史.记录)
    .entries()
    .map(([id, value]) => ({ id, ...value }))
    .reverse()
    .value();
}

export function 读取单位详情(state: GoblinState, id: string) {
  return state.冒险者库[id] ?? state.哥布林库[id] ?? null;
}

export function 读取基础状态(raw: unknown) {
  try {
    return Schema.parse(raw ?? DefaultData);
  } catch {
    return DefaultData;
  }
}
